WaveLinkInputFilterEnable.example:
string input = CPH.WaveLinkGetInputIdentifier("Mic");
string filter = CPH.WaveLinkInputGetFilterIdentifier(input, "Reverb");
CPH.WaveLinkInputFilterEnable(input, filter);

WaveLinkInputFilterDisable.example:
string input = CPH.WaveLinkGetInputIdentifier("Mic");
string filter = CPH.WaveLinkInputGetFilterIdentifier(input, "Reverb");
CPH.WaveLinkInputFilterDisable(input, filter);

WaveLinkInputFilterToggle.example:
string input = CPH.WaveLinkGetInputIdentifier("Mic");
string filter = CPH.WaveLinkInputGetFilterIdentifier(input, "Reverb");
CPH.WaveLinkInputFilterToggle(input, filter);

WaveLinkInputGetFilterIdentifier.example:
string input = CPH.WaveLinkGetInputIdentifier("Mic");
string filter = CPH.WaveLinkInputGetFilterIdentifier(input, "Reverb");
CPH.LogInfo($"Reverb id: {filter}");

WaveLinkInputGetFilterState.example:
string input = CPH.WaveLinkGetInputIdentifier("Mic");
bool on = CPH.WaveLinkInputGetFilterState(input, "Reverb");
CPH.LogInfo($"Reverb on: {on}");

WaveLinkMicrophoneGetVolume.example:
string mic = CPH.WaveLinkGetMicrophoneIdentifier("Wave:3");
double gain = CPH.WaveLinkMicrophoneGetVolume(mic);
CPH.LogInfo($"Mic gain: {gain}");
